      {children}
    </div>
  );
}

function AriaBox({ tip }) {
  return (
    <div style={{ background:'linear-gradient(135deg,#F5F4FF,#EDE9FF)', border:'1.5px solid #D0CBFF', borderRadius:14, padding:'13px 16px', display:'flex', gap:12, alignItems:'flex-start', marginTop:14 }}>
